      /* (2245) with_recursive_tail ::= */ yytestcase(yyruleno==2245);
      /* (2251) with_cte_column_tail ::= */ yytestcase(yyruleno==2251);
      /* (2258) with_cte_body_nested ::= */ yytestcase(yyruleno==2258);
      /* (2278) table_query_tail ::= */ yytestcase(yyruleno==2278);
      /* (2281) table_offset_tail ::= */ yytestcase(yyruleno==2281);
      /* (2286) values_row_contents ::= */ yytestcase(yyruleno==2286);
      /* (2302) values_row_nested_tokens ::= */ yytestcase(yyruleno==2302);
      /* (2314) values_query_tail ::= */ yytestcase(yyruleno==2314);
      /* (2339) values_order_direction ::= */ yytestcase(yyruleno==2339);
      /* (2347) execute_tail ::= */ yytestcase(yyruleno==2347);
      /* (2388) signal_set_tail ::= */ yytestcase(yyruleno==2388);
